#!/usr/bin/env bash\nset -e\n\n# Mock rationale: Use a temporary file to capture GITHUB_OUTPUT without touching the real environment\nexport GITHUB_OUTPUT=$(mktemp)\n\ndeclare -A expected=([feat]="✨" [fix]="🐛" [docs]="📚" [chore]="🧹" [refactor]="🔧" [test]="✅" [style]="💄" [perf]="⚡" [build]="🏗️" [ci]="🤖" [revert]="⏪" [unknown]="❓")\n\nfor type in "${!expected[@]}"; do\n  bash src/emoji.sh "$type"\n  result=$(grep '^emoji=' "$GITHUB_OUTPUT" | cut -d'=' -f2- )\n  if [[ "$result" != "${expected[$type]}" ]]; then\n    echo "Test failed for type '$type': expected '${expected[$type]}', got '$result'"\n    exit 1\n  fi\n  # Reset the mock output file for the next iteration\n  > "$GITHUB_OUTPUT"\ndone\n\necho "All emoji mapping tests passed."
